using System.Text.Json;
using System.Text.RegularExpressions;
using AwesomeAssertions;

namespace XConnect.Tests;

/// <summary>
/// Checks the source code against <c>docs/spec-snapshot.json</c> (a compact snapshot of the official OpenAPI document, regenerated by
/// <c>tools/generate_coverage.py</c>) and against <c>docs/api-coverage.md</c>. If you add or change an endpoint and these fail, run the generator.
/// </summary>
public sealed partial class SpecConformanceTests
{
    [Flags]
    private enum Auth
    {
        OAuth1 = 1,
        OAuth2 = 2,
        App = 4,
        User = OAuth1 | OAuth2,
        Any = OAuth1 | OAuth2 | App,
    }

    private static readonly string Root = FindRoot();

    internal static string RepositoryRoot => Root;

    // Endpoints reached through shared helpers rather than a literal Create(...) call, with the authentication each helper passes.
    private static readonly Dictionary<string, Auth> HelperRoutes = new()
    {
        ["GET /2/tweets/search/recent"] = Auth.Any,
        ["GET /2/tweets/search/all"] = Auth.Any,
        ["GET /2/tweets/counts/recent"] = Auth.OAuth2 | Auth.App,
        ["GET /2/tweets/counts/all"] = Auth.App,
        ["GET /2/tweets/sample/stream"] = Auth.App,
        ["GET /2/tweets/search/stream"] = Auth.App,
        ["GET /2/tweets/sample10/stream"] = Auth.App,
        ["GET /2/tweets/firehose/stream"] = Auth.App,
        ["GET /2/tweets/firehose/stream/lang/en"] = Auth.App,
        ["GET /2/tweets/firehose/stream/lang/ja"] = Auth.App,
        ["GET /2/tweets/firehose/stream/lang/ko"] = Auth.App,
        ["GET /2/tweets/firehose/stream/lang/pt"] = Auth.App,
        ["GET /2/users/{id}/followers"] = Auth.Any,
        ["GET /2/users/{id}/following"] = Auth.Any,
        ["GET /2/users/{id}/affiliates"] = Auth.Any,
        ["GET /2/dm_events"] = Auth.User,
        ["GET /2/dm_conversations/{id}/dm_events"] = Auth.User,
        ["GET /2/dm_conversations/with/{participant_id}/dm_events"] = Auth.User,
        ["POST /2/users/{id}/following"] = Auth.User,
        ["POST /2/users/{id}/blocking"] = Auth.User,
        ["POST /2/users/{id}/muting"] = Auth.User,
        ["DELETE /2/users/{source_user_id}/following/{target_user_id}"] = Auth.User,
        ["DELETE /2/users/{source_user_id}/blocking/{target_user_id}"] = Auth.User,
        ["DELETE /2/users/{source_user_id}/muting/{target_user_id}"] = Auth.User,
    };

    private sealed record Operation(string Method, string Path, string[] Auth, string[] Scopes)
    {
        public string Key => $"{Method} {Path}";
    }

    private static Dictionary<string, Operation> LoadSpec(out string version)
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(Root, "docs/spec-snapshot.json")));
        version = doc.RootElement.GetProperty("specVersion").GetString()!;
        return doc.RootElement.GetProperty("operations").EnumerateArray()
            .Select(o => new Operation(
                o.GetProperty("method").GetString()!,
                o.GetProperty("path").GetString()!,
                [.. o.GetProperty("auth").EnumerateArray().Select(a => a.GetString()!)],
                [.. o.GetProperty("scopes").EnumerateArray().Select(a => a.GetString()!)]))
            .ToDictionary(o => o.Key);
    }

    private static Auth FromSpec(IEnumerable<string> names) =>
        names.Aggregate((Auth)0, (acc, n) => acc | n switch { "OAuth 1.0a" => Auth.OAuth1, "OAuth 2.0" => Auth.OAuth2, "App-only" => Auth.App, _ => 0 });

    private static Auth Decode(string expression) =>
        expression.Split('|').Select(p => p.Trim()).Aggregate((Auth)0, (acc, p) => acc | p switch
        {
            "XAuthMethods.UserContext" => Auth.User,
            "XAuthMethods.Any" => Auth.Any,
            "XAuthMethods.AppOnly" => Auth.App,
            "XAuthMethods.OAuth2User" => Auth.OAuth2,
            "XAuthMethods.OAuth1" => Auth.OAuth1,
            "Auth" => Auth.OAuth2 | Auth.App, // XSpacesClient.Auth
            _ => throw new InvalidOperationException($"Unrecognised authentication expression '{expression}'; extend Decode."),
        });

    private static (Dictionary<string, Auth> Literal, HashSet<string> All) ScanSource()
    {
        var literal = new Dictionary<string, Auth>();
        var all = new HashSet<string>();
        foreach (var file in Directory.EnumerateFiles(Path.Combine(Root, "src/XConnect"), "*.cs", SearchOption.AllDirectories)
                     .Where(f => !f.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}") && !f.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}")))
        {
            var text = File.ReadAllText(file);
            foreach (Match m in CreateCall().Matches(text))
            {
                var key = $"{m.Groups[1].Value.ToUpperInvariant()} {m.Groups[2].Value}";
                literal[key] = Decode(m.Groups[3].Value);
                all.Add(key);
            }

            foreach (Match m in HelperCall().Matches(text))
            {
                all.Add($"GET {m.Groups[1].Value}");
            }

            foreach (Match m in TargetCall().Matches(text))
            {
                all.Add($"{m.Groups[1].Value.ToUpperInvariant()} {m.Groups[2].Value}");
            }

            foreach (Match m in UntargetCall().Matches(text))
            {
                all.Add($"DELETE {m.Groups[1].Value}");
            }

            if (file.EndsWith("StreamingClient.cs", StringComparison.Ordinal))
            {
                foreach (Match m in StreamRoute().Matches(text))
                {
                    all.Add($"GET {m.Groups[1].Value}");
                }
            }
        }

        return (literal, all);
    }

    [Fact]
    public void EveryRouteTheSdkCalls_ExistsInTheSpecification_WithTheSameMethod()
    {
        var spec = LoadSpec(out _);
        var (_, all) = ScanSource();

        all.Should().NotBeEmpty();
        all.Where(k => !spec.ContainsKey(k)).Should().BeEmpty("every route and HTTP method must be in the official OpenAPI document");
    }

    [Fact]
    public void EveryRoute_OnlyUsesAuthenticationMethodsTheSpecificationAllows()
    {
        var spec = LoadSpec(out _);
        var (literal, all) = ScanSource();
        var problems = new List<string>();

        foreach (var key in all)
        {
            var sent = literal.TryGetValue(key, out var a) ? a
                : HelperRoutes.TryGetValue(key, out var h) ? h
                : throw new InvalidOperationException($"No authentication known for {key}: add it to HelperRoutes.");
            var allowed = FromSpec(spec[key].Auth);
            if ((sent & ~allowed) != 0)
            {
                problems.Add($"{key}: SDK accepts {sent} but the specification allows {allowed}");
            }
        }

        problems.Should().BeEmpty();
    }

    [Fact]
    public void EveryRoute_DeclaresAtLeastOneAuthenticationMethodThatIsUsable()
    {
        var spec = LoadSpec(out _);
        var (_, all) = ScanSource();

        all.Where(k => FromSpec(spec[k].Auth) == 0).Should().BeEmpty("an endpoint with no documented authentication cannot be called");
    }

    [Fact]
    public void CoverageMatrix_ListsExactlyTheRoutesTheCodeImplements()
    {
        var spec = LoadSpec(out var version);
        var (_, all) = ScanSource();
        var matrix = File.ReadAllText(Path.Combine(Root, "docs/api-coverage.md"));

        var supported = SupportedRow().Matches(matrix).Select(m => $"{m.Groups[1].Value} {m.Groups[2].Value}").ToHashSet();

        supported.Should().BeEquivalentTo(all, "docs/api-coverage.md is generated and must match the code; run tools/generate_coverage.py");
        matrix.Should().Contain($"version **{version}**");
        matrix.Should().Contain($"**Total: {spec.Count} operations.");
    }

    [Fact]
    public void CoverageMatrix_HasNoUntestedSupportedOperation() =>
        File.ReadAllText(Path.Combine(Root, "docs/api-coverage.md")).Should().NotContain("**NONE**");

    private static string FindRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "XConnect.sln")))
        {
            dir = dir.Parent;
        }

        return dir?.FullName ?? throw new InvalidOperationException("Could not locate the repository root (XConnect.sln).");
    }

    [GeneratedRegex(@"Create\(\s*HttpMethod\.(\w+),\s*""(/2/[^""]+)"",\s*([^,)]+(?: \| XAuthMethods\.\w+)?)")]
    private static partial Regex CreateCall();

    [GeneratedRegex(@"(?:Search|Counts|Stream|Page|Events)\(\s*""(/2/[^""]+)""")]
    private static partial Regex HelperCall();

    [GeneratedRegex(@"\bTarget\(\s*HttpMethod\.(\w+),\s*""(/2/[^""]+)""")]
    private static partial Regex TargetCall();

    [GeneratedRegex(@"Untarget\(\s*""(/2/[^""]+)""")]
    private static partial Regex UntargetCall();

    [GeneratedRegex(@"=>\s*""(/2/tweets/[^""]+/stream[^""]*)""")]
    private static partial Regex StreamRoute();

    [GeneratedRegex(@"^\| (\w+) \| `([^`]+)` \| Supported \|", RegexOptions.Multiline)]
    private static partial Regex SupportedRow();
}
